public final class EtfMonitorChecks {
 private static int checks;private interface Work{void run()throws Exception;}
 private static void ok(boolean value)throws Exception{if(!value)throw new Exception("ETF monitor assertion failed");checks++;}
 private static void rejects(Work work)throws Exception{boolean bad=false;try{work.run();}catch(Exception e){bad=true;}ok(bad);}
 static JSONObject fixture()throws Exception{JSONArray bars=new JSONArray();for(int n=0;n<10;n++)bars.put(new JSONObject().put("time",String.format(Locale.ROOT,"2026-10-12 14:%02d:00",51+n).replace("14:60","15:00")).put("price",4.6).put("amount",n<5?100:150));return new JSONObject().put("schema","native-etf-monitor/v1").put("provider","host-held-etf").put("receivedAt","2026-10-12T07:01:00Z").put("items",new JSONArray().put(new JSONObject().put("id","SH:etf:510300").put("name","沪深300ETF").put("symbol","sh510300").put("quote",new JSONObject().put("symbol","sh510300").put("source","新浪公开报价").put("price",4.6).put("changePercent",1.2).put("amount",100000).put("tradeDate","2026-10-12").put("tradeTime","15:00:00").put("checkedAt","2026-10-12T07:01:00Z").put("cached",true)).put("minuteInput",new JSONObject().put("source","tencent-1m").put("intervalMinutes",1).put("amountUnit","CNY").put("checkedAt","2026-10-12T07:01:00Z").put("rows",bars))));}
 public static void main(String[] args)throws Exception{model();System.out.println("EtfMonitor model PASS "+checks);}
 public static void model()throws Exception{JSONObject snapshot=EtfMonitorModel.snapshot(fixture()),r=snapshot.getJSONArray("items").getJSONObject(0),m=r.getJSONObject("momentum");ok(m.getDouble("rolling5AmountYuan")==750);ok(m.getDouble("previous5AmountYuan")==500);ok(m.getDouble("rolling5ChangePct")==50);ok(!m.getBoolean("realtimeGuaranteed"));ok(r.getJSONObject("quote").getString("sourceTime").equals("2026-10-12T15:00:00+08:00"));ok(EtfMonitorModel.equal(EtfMonitorModel.snapshot(snapshot),snapshot));for(String id:new String[]{"SH:stock:510300","IF0","510300","SZ:index:159915"})rejects(()->{JSONObject input=fixture();input.getJSONArray("items").getJSONObject(0).put("id",id);EtfMonitorModel.snapshot(input);});rejects(()->{JSONObject input=fixture();input.getJSONArray("items").getJSONObject(0).getJSONObject("quote").put("symbol","sz159915");EtfMonitorModel.snapshot(input);});JSONObject input=fixture();JSONObject missing=new JSONObject().put("id","SZ:etf:159915").put("name","创业板ETF");input.put("items",new JSONArray().put(missing).put(input.getJSONArray("items").getJSONObject(0)));JSONObject normalized=EtfMonitorModel.snapshot(input);ok(normalized.getJSONArray("items").getJSONObject(0).getJSONObject("quote").isNull("amount"));for(boolean ascending:new boolean[]{true,false})ok(EtfMonitorModel.rows(normalized,new JSONObject().put("sort","amount").put("ascending",ascending)).getJSONObject(0).getString("id").equals("SH:etf:510300"));ok(EtfMonitorModel.rows(normalized,new JSONObject().put("search","创业板")).length()==1);
  input=fixture();JSONArray bars=input.getJSONArray("items").getJSONObject(0).getJSONObject("minuteInput").getJSONArray("rows");for(int n=0;n<bars.length();n++){bars.getJSONObject(n).remove("amount");bars.getJSONObject(n).put("volume",1000);}m=EtfMonitorModel.snapshot(input).getJSONArray("items").getJSONObject(0).getJSONObject("momentum");ok(m.isNull("rolling5AmountYuan"));ok(m.isNull("latestMinuteAmountYuan"));input=fixture();bars=input.getJSONArray("items").getJSONObject(0).getJSONObject("minuteInput").getJSONArray("rows");bars.put(bars.getJSONObject(bars.length()-1));ok(EtfMonitorModel.snapshot(input).getJSONArray("items").getJSONObject(0).getJSONObject("momentum").isNull("rolling5AmountYuan"));input=fixture();bars=input.getJSONArray("items").getJSONObject(0).getJSONObject("minuteInput").getJSONArray("rows");for(int n=0;n<5;n++)bars.getJSONObject(n).put("amount",0);m=EtfMonitorModel.snapshot(input).getJSONArray("items").getJSONObject(0).getJSONObject("momentum");ok(m.getDouble("previous5AmountYuan")==0);ok(m.isNull("rolling5ChangePct"));
  JSONObject raw=new JSONObject().put("code",0).put("data",new JSONObject().put("sh510300",new JSONObject().put("data",new JSONObject().put("date","20261012").put("data",new JSONArray().put("0930 4.6 100 1000").put("0931 4.6 200 1200").put("0932 4.6 250 1100").put("0934 4.6 300 1400").put("0935 4.6 400")))));JSONObject minute=EtfMonitorModel.tencentMinute(raw,"SH:etf:510300","2026-10-12T01:40:00Z");bars=minute.getJSONArray("rows");ok(bars.getJSONObject(0).isNull("amount"));ok(bars.getJSONObject(1).getDouble("amount")==200);for(int n=2;n<5;n++)ok(bars.getJSONObject(n).isNull("amount"));rejects(()->EtfMonitorModel.tencentMinute(raw,"SZ:etf:159915","2026-10-12T01:40:00Z"));JSONObject archived=EtfMonitorModel.append(EtfMonitorModel.emptyArchive(),fixture(),"2026-10-12T07:02:00Z"),failed=EtfMonitorModel.failed(archived,"failed","2026-10-13T01:00:00Z","Bearer sk-fixture-secret");ok(EtfMonitorModel.equal(archived.getJSONArray("frames"),failed.getJSONArray("frames")));ok(!failed.toString().contains("sk-fixture-secret"));ok(EtfMonitorModel.equal(EtfMonitorModel.frame(failed,""),EtfMonitorModel.snapshot(fixture())));}
 private static void mainThread(Work work)throws Exception{if(Looper.myLooper()==Looper.getMainLooper()){work.run();return;}CountDownLatch done=new CountDownLatch(1);Exception[] errors={null};new Handler(Looper.getMainLooper()).post(()->{try{work.run();}catch(Exception e){errors[0]=e;}finally{done.countDown();}});ok(done.await(20,TimeUnit.SECONDS));if(errors[0]!=null)throw errors[0];}
 public static void store(Context context)throws Exception{File file=new File(context.getCacheDir(),"etf-monitor-"+System.nanoTime()+".json");EtfMonitorStore store=new EtfMonitorStore(file);JSONObject first=EtfMonitorModel.append(store.read(),fixture(),"2026-10-12T07:02:00Z");store.save(first,0);ok(EtfMonitorModel.equal(store.read(),first));JSONObject next=EtfMonitorModel.failed(first,"failed","2026-10-13T01:00:00Z","EOF");store.save(next,1);rejects(()->store.save(first,0));ok(EtfMonitorModel.equal(store.read(),next));File foreign=new File(context.getCacheDir(),"etf-foreign-"+System.nanoTime()+".json");byte[] original="{\"schema\":\"other\",\"preserve\":true}".getBytes(StandardCharsets.UTF_8);try(FileOutputStream out=new FileOutputStream(foreign)){out.write(original);}rejects(()->new EtfMonitorStore(foreign).save(first,0));try(InputStream in=new FileInputStream(foreign)){ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] buffer=new byte[128];for(int n;(n=in.read(buffer))!=-1;)out.write(buffer,0,n);ok(Arrays.equals(original,out.toByteArray()));}file.delete();foreign.delete();}
 public static void ui(Context context)throws Exception{mainThread(()->{File file=new File(context.getCacheDir(),"etf-ui-"+System.nanoTime()+".json");List<String> tickets=new ArrayList<>();String[] opened={""};EtfMonitorScreen screen=new EtfMonitorScreen(context,file,new EtfMonitorScreen.Host(){public void openChart(String id,String period){opened[0]=id;}public boolean supportsRefresh(){return true;}public void refresh(String token,JSONObject selection)throws Exception{ok(selection.getJSONArray("ids").length()<=24);tickets.add(token);}});screen.setSnapshot(fixture());screen.<Button>findViewWithTag("etfMonitorOpen").performClick();ok(opened[0].equals("SH:etf:510300"));screen.<Button>findViewWithTag("etfMonitorRefreshQuotes").performClick();ok(tickets.size()==1);screen.cancel();JSONObject before=new EtfMonitorStore(file).read();screen.acceptSnapshot(tickets.get(0),fixture());ok(EtfMonitorModel.equal(new EtfMonitorStore(file).read(),before));screen.<Button>findViewWithTag("etfMonitorRefreshMinute").performClick();screen.failRefresh(tickets.get(1),"EOF");ok(EtfMonitorModel.equal(new EtfMonitorStore(file).read().getJSONArray("frames"),before.getJSONArray("frames")));EtfMonitorScreen reopened=new EtfMonitorScreen(context,file,(id,period)->{});ok(new JSONObject(new String(reopened.exportEvidence(),StandardCharsets.UTF_8)).getJSONArray("items").length()==1);screen.close();reopened.close();file.delete();});}
 public static void geometry(Context context)throws Exception{mainThread(()->{File file=new File(context.getCacheDir(),"etf-layout-"+System.nanoTime()+".json");EtfMonitorScreen screen=new EtfMonitorScreen(context,file,(id,period)->{});screen.setSnapshot(fixture());float density=context.getResources().getDisplayMetrics().density;for(int[] size:new int[][]{{420,640},{840,190}}){screen.measure(View.MeasureSpec.makeMeasureSpec(Math.round(size[0]*density),View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(Math.round(size[1]*density),View.MeasureSpec.EXACTLY));screen.layout(0,0,screen.getMeasuredWidth(),screen.getMeasuredHeight());ok(((ScrollView)screen.getChildAt(2)).getMeasuredHeight()>Math.round(45*density));ok(screen.<Button>findViewWithTag("etfMonitorOpen").getMeasuredHeight()>=Math.round(48*density));for(boolean dark:new boolean[]{false,true}){screen.setDarkTheme(dark);Button open=screen.findViewWithTag("etfMonitorOpen");ok(open.getCurrentTextColor()!=open.getBackgroundTintList().getDefaultColor());}}screen.close();file.delete();});}
}
